from __future__ import absolute_import, division, print_function, unicode_literals

import sys

PY2 = sys.version_info[0] == 2

if PY2:
    text_type = unicode
    binary_type = str
    string_types = (basestring,)
    integer_types = (int, long)
    from itertools import imap as map
    from itertools import izip as zip
    from urllib2 import Request, urlopen
    from urlparse import urlparse
else:
    text_type = str
    binary_type = bytes
    string_types = (str,)
    integer_types = (int,)
    map = map
    zip = zip
    from urllib.request import Request, urlopen
    from urllib.parse import urlparse


def to_unicode(value, encoding="utf-8", errors="strict"):
    if isinstance(value, text_type):
        return value
    if isinstance(value, binary_type):
        return value.decode(encoding, errors)
    return text_type(value)


def to_bytes(value, encoding="utf-8", errors="strict"):
    if isinstance(value, binary_type):
        return value
    if isinstance(value, text_type):
        return value.encode(encoding, errors)
    return binary_type(value)


if PY2:
    def iteritems(mapping):
        return mapping.iteritems()
else:
    def iteritems(mapping):
        return iter(mapping.items())

from __future__ import absolute_import, division, print_function, unicode_literals

from ._compat import iteritems, string_types, text_type


def greet(name):
    if not isinstance(name, string_types):
        raise TypeError("name must be a string")
    return "Hello, {0}!".format(name)


def merge(*mappings):
    result = {}
    for mapping in mappings:
        for key, value in iteritems(mapping):
            result[key] = value
    return result


def normalize(text):
    if not isinstance(text, text_type):
        text = text.decode("utf-8")
    return " ".join(text.split()).strip()

from __future__ import absolute_import, division, print_function, unicode_literals

import pytest

from mylib import greet, merge, normalize
from mylib._compat import PY2, text_type


def test_greet():
    assert greet("world") == "Hello, world!"


def test_greet_rejects_non_string():
    with pytest.raises(TypeError):
        greet(42)


def test_merge():
    assert merge({"a": 1}, {"b": 2}, {"a": 3}) == {"a": 3, "b": 2}


def test_normalize_unicode():
    assert normalize("  hello\tworld  ") == "hello world"


def test_normalize_bytes():
    assert normalize(b"  hello\tworld  ") == "hello world"


def test_text_type_is_unicode_everywhere():
    assert text_type("x") == "x"
    assert not isinstance(text_type("x"), bytes if not PY2 else str)

